/*
  Zusatzdaten für die Szene system-module (Einstellungen > System und Catering, Module, Betrieb).
  Läuft einmal auf seed.sql. Alles fiktiv. Datumswerte sind relativ zum Ausführungszeitpunkt.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

DECLARE @now datetime = GETUTCDATE();

-- Ereignisanzeige: eigene Quelle, damit die Szene nur diese Einträge zeigt und keine Laufzeitmeldungen der lokalen Instanz.
INSERT Logging(Source,EventType,DateTimeStamp,Context,Message,UserDomainName,MachineName,ProcessId,ThreadId,StackTrace,Exception,Data,UserName)
SELECT 'RoomsPro.Worker',v.e,DATEADD(minute,-v.m,@now),'',v.t,'MUSTER','ROOMS-APP01',4120,'12','','','',''
FROM (VALUES
 ('Information',  4,'Kalenderabgleich abgeschlossen: 128 Termine geprüft, 2 Differenzen gefunden.'),
 ('Information', 19,'Benachrichtigungen versendet: 6 E-Mails an Teilnehmende.'),
 ('Warning',     37,'Postfach saentis@muster-ag.example: Antwort von Exchange verzögert, neuer Versuch in 5 Minuten.'),
 ('Information', 52,'Webhook-Abonnemente erneuert: 14 Postfächer.'),
 ('Error',       68,'Personenimport HR-System: Zeile 42 enthält keine gültige E-Mail-Adresse.'),
 ('Information', 95,'Personenimport HR-System abgeschlossen: 212 Personen geprüft, 3 aktualisiert.'),
 ('Warning',    121,'Temporäre Buchungen bereinigt: 2 Blockierungen waren abgelaufen.'),
 ('Information',146,'Kalenderabgleich abgeschlossen: 131 Termine geprüft, keine Differenzen gefunden.'),
 ('Information',203,'Erinnerungen versendet: 11 E-Mails.'),
 ('Error',      247,'Postfach sandra.frei@muster-ag.example: Termin konnte nicht aktualisiert werden, Exchange meldet einen Zeitkonflikt.'),
 ('Information',301,'Buchungsexport Controlling abgeschlossen: 87 Buchungen exportiert.'),
 ('Information',362,'Kalenderabgleich abgeschlossen: 127 Termine geprüft, keine Differenzen gefunden.')
) v(e,m,t);

-- Notification Tracking: Versandhistorie zu bestehenden Buchungen.
INSERT AktionHistory(AktiontypId,DateTimeStamp,PersonId,ReservationId,NotifikationtypId,AktionXml,Name)
SELECT 2,DATEADD(minute,-v.m,@now),r.PersonOrganisatorId,r.Id,v.n,'<AktionSendMail />',N'E-Mail'
FROM (VALUES (6,1,N'Budgetworkshop'),(24,2,N'Budgetworkshop'),(48,1,N'Kundentag Workshop'),(75,5,N'Kundentag Workshop'),(130,1,N'Mitarbeiterversammlung'),(190,2,N'Mitarbeiterversammlung'),(260,9,N'Projektsitzung Intranet'),(340,4,N'Nachbesprechung Intranet'))
 v(m,n,titel)
CROSS APPLY (SELECT TOP 1 Id,PersonOrganisatorId FROM Reservation WHERE Titel=v.titel ORDER BY Id) r;

-- Daten Importe/Exporte: geplante Aktionen ein Jahr in der Zukunft, damit sie nicht laufen.
INSERT Aktion(AktiontypId,PersonId,Ausführung,Intervall,Name,AktionXml)
VALUES (1,1,DATEADD(year,1,@now),1440,N'Personenimport HR-System','<Tasks />'),
       (1,1,DATEADD(year,1,@now),10080,N'Buchungsexport Controlling','<Tasks />');

-- Sync-Differenzen: je eine Abweichung bei Titel, Zeit und fehlendem Termin.
DECLARE @r int,@p int,@b datetime,@e datetime,@m nvarchar(320),@t nvarchar(200);

SELECT TOP 1 @r=r.Id,@p=r.PersonOrganisatorId,@b=r.Beginn,@e=r.Ende,@t=r.Titel,@m=p.Mail FROM Reservation r JOIN Person p ON p.Id=r.PersonOrganisatorId WHERE r.Titel=N'Budgetworkshop' ORDER BY r.Id;
INSERT CalendarSyncDriftFinding(BookingId,CandidateId,CandidateEndUtc,CandidateStartUtc,CandidateType,DifferenceFlags,DriftHash,ExchangeLastChangedAtUtc,ExchangeSnapshotJson,FirstDetectedAtUtc,LastCheckedAtUtc,LastDetectedAtUtc,Mailbox,MostRecentChangeSource,PersonId,Provider,ResolutionAction,RoomsLastChangedAtUtc,RoomsSnapshotJson,Status,SyncItemId,SuggestedResolution,SuggestionReason)
SELECT @r,@r,@e,@b,0,1,'seed-1',DATEADD(hour,-2,@now),
 CONCAT('{"subject":"Budgetworkshop 2027","startUtc":"',CONVERT(char(19),@b,126),'Z","endUtc":"',CONVERT(char(19),@e,126),'Z","lastModifiedAtUtc":"',CONVERT(char(19),DATEADD(hour,-2,@now),126),'Z","isMissing":false}'),
 DATEADD(hour,-1,@now),DATEADD(hour,-1,@now),DATEADD(hour,-1,@now),@m,2,@p,2,0,DATEADD(day,-3,@now),
 CONCAT('{"title":"',@t,'","startUtc":"',CONVERT(char(19),@b,126),'Z","endUtc":"',CONVERT(char(19),@e,126),'Z","lastChangedAtUtc":"',CONVERT(char(19),DATEADD(day,-3,@now),126),'Z"}'),
 0,'demo-item-1',1,'ExchangeNewer';

SELECT TOP 1 @r=r.Id,@p=r.PersonOrganisatorId,@b=r.Beginn,@e=r.Ende,@t=r.Titel,@m=p.Mail FROM Reservation r JOIN Person p ON p.Id=r.PersonOrganisatorId WHERE r.Titel=N'Kundentag Workshop' ORDER BY r.Id;
INSERT CalendarSyncDriftFinding(BookingId,CandidateId,CandidateEndUtc,CandidateStartUtc,CandidateType,DifferenceFlags,DriftHash,ExchangeLastChangedAtUtc,ExchangeSnapshotJson,FirstDetectedAtUtc,LastCheckedAtUtc,LastDetectedAtUtc,Mailbox,MostRecentChangeSource,PersonId,Provider,ResolutionAction,RoomsLastChangedAtUtc,RoomsSnapshotJson,Status,SyncItemId,SuggestedResolution,SuggestionReason)
SELECT @r,@r,@e,@b,0,2,'seed-2',DATEADD(hour,-5,@now),
 CONCAT('{"subject":"',@t,'","startUtc":"',CONVERT(char(19),DATEADD(hour,1,@b),126),'Z","endUtc":"',CONVERT(char(19),DATEADD(hour,1,@e),126),'Z","lastModifiedAtUtc":"',CONVERT(char(19),DATEADD(hour,-5,@now),126),'Z","isMissing":false}'),
 DATEADD(hour,-1,@now),DATEADD(hour,-1,@now),DATEADD(hour,-1,@now),@m,2,@p,2,0,DATEADD(day,-6,@now),
 CONCAT('{"title":"',@t,'","startUtc":"',CONVERT(char(19),@b,126),'Z","endUtc":"',CONVERT(char(19),@e,126),'Z","lastChangedAtUtc":"',CONVERT(char(19),DATEADD(day,-6,@now),126),'Z"}'),
 0,'demo-item-2',1,'ExchangeNewer';

SELECT TOP 1 @r=r.Id,@p=r.PersonOrganisatorId,@b=r.Beginn,@e=r.Ende,@t=r.Titel,@m=p.Mail FROM Reservation r JOIN Person p ON p.Id=r.PersonOrganisatorId WHERE r.Titel=N'Mitarbeiterversammlung' ORDER BY r.Id;
INSERT CalendarSyncDriftFinding(BookingId,CandidateId,CandidateEndUtc,CandidateStartUtc,CandidateType,DifferenceFlags,DriftHash,ExchangeSnapshotJson,FirstDetectedAtUtc,LastCheckedAtUtc,LastDetectedAtUtc,Mailbox,MostRecentChangeSource,PersonId,Provider,ResolutionAction,RoomsLastChangedAtUtc,RoomsSnapshotJson,Status,SyncItemId,SuggestedResolution,SuggestionReason)
SELECT @r,@r,@e,@b,0,4,'seed-3',
 '{"isMissing":true}',
 DATEADD(hour,-1,@now),DATEADD(hour,-1,@now),DATEADD(hour,-1,@now),@m,1,@p,2,0,DATEADD(day,-1,@now),
 CONCAT('{"title":"',@t,'","startUtc":"',CONVERT(char(19),@b,126),'Z","endUtc":"',CONVERT(char(19),@e,126),'Z","lastChangedAtUtc":"',CONVERT(char(19),DATEADD(day,-1,@now),126),'Z"}'),
 0,'demo-item-3',2,'ExchangeMissing';

COMMIT;

-- Weitere Dienstleister und eine zweite Angebotszone. Ohne Ressourcen, damit sie in Buchungen nicht auftauchen.
BEGIN TRAN;
DECLARE @d TABLE(n int, dl int, b nvarchar(100), t nvarchar(200));
DECLARE @o1 uniqueidentifier, @o2 uniqueidentifier, @id int, @name nvarchar(100), @text nvarchar(200);
DECLARE c CURSOR LOCAL FOR SELECT b,t FROM (VALUES (N'Bestuhlungsdienst Muster',N'Stellt die Bestuhlung in den Räumen um'),(N'Getränke Frisch & Co',N'Externer Getränkehändler')) v(b,t);
OPEN c; FETCH NEXT FROM c INTO @name,@text;
WHILE @@FETCH_STATUS=0
BEGIN
  SET @o1=NEWID(); SET @o2=NEWID();
  INSERT Dienstleister(BezeichnungOid,BeschreibungOid) VALUES(@o1,@o2);
  SET @id=SCOPE_IDENTITY();
  INSERT Text(TableName,RecordId,FieldOid,FieldName,LanguageId,Value) VALUES('Dienstleister',CAST(@id AS varchar(20)),@o1,'BezeichnungOid','de',@name),('Dienstleister',CAST(@id AS varchar(20)),@o2,'BeschreibungOid','de',@text);
  FETCH NEXT FROM c INTO @name,@text;
END
CLOSE c; DEALLOCATE c;

SET @o1=NEWID(); SET @o2=NEWID();
INSERT Angebotszone(DienstleisterId,GruppeId,BezeichnungOid,BeschreibungOid,Beginn,Ende,Vorlaufdauer,Nachlaufdauer,NotifikationTageImVoraus,KostenBetrag,KostenWaehrung,AnnullationKostenBetrag,AnnullationKostenWaehrung,AnnullationKostenStart,IstDLFuerHauptressource,IstDLFuerZusatzressourcen,IstDLFuerBestuhlung,MontagBeginn,MontagEnde,DienstagBeginn,DienstagEnde,MittwochBeginn,MittwochEnde,DonnerstagBeginn,DonnerstagEnde,FreitagBeginn,FreitagEnde,SamstagBeginn,SamstagEnde,SonntagBeginn,SonntagEnde,KundeXml)
SELECT @id,GruppeId,@o1,@o2,Beginn,Ende,Vorlaufdauer,Nachlaufdauer,NotifikationTageImVoraus,KostenBetrag,KostenWaehrung,AnnullationKostenBetrag,AnnullationKostenWaehrung,AnnullationKostenStart,IstDLFuerHauptressource,IstDLFuerZusatzressourcen,IstDLFuerBestuhlung,MontagBeginn,MontagEnde,DienstagBeginn,DienstagEnde,MittwochBeginn,MittwochEnde,DonnerstagBeginn,DonnerstagEnde,FreitagBeginn,FreitagEnde,SamstagBeginn,SamstagEnde,SonntagBeginn,SonntagEnde,KundeXml FROM Angebotszone WHERE Id=1;
SET @id=SCOPE_IDENTITY();
INSERT Text(TableName,RecordId,FieldOid,FieldName,LanguageId,Value) VALUES('Angebotszone',CAST(@id AS varchar(20)),@o1,'BezeichnungOid','de',N'Getränke Bern'),('Angebotszone',CAST(@id AS varchar(20)),@o2,'BeschreibungOid','de',N'Getränkelieferungen an den Standort Bern');
COMMIT;

