INSERT Logon(LogontypId,PersonId,Name,Passwort,IstImportiert,MaskedIdentifier,FailedLogins,AllowBackendLogon)
VALUES (4,13,N'onsite.pin',N'482916',0,NEWID(),0,0);
UPDATE Konfiguration SET Wert='12' WHERE Id=64 AND ISNULL(Wert,'')='';
INSERT TuerschildKonfiguration(RessourceId,KulturId,AnfrageIntervall,TitelAnzeigen,OrganisatorAnzeigen,TimeStamp,CheckoutMode,RessourceBeschreibungAnzeigen,DsReadOnly,CheckinOnly,UnauthorizedActions,ConfigurationInterval,EnableDebugPage,MaxFutureBookings,ScreenReloadInterval)
SELECT r.Id,(SELECT TOP 1 Id FROM Kultur),1,1,1,GETUTCDATE(),'Terminate',0,0,0,1,15,0,3,60 FROM Ressource r WHERE r.Name IN (N'Jungfrau',N'Pilatus');

